<?php declare(strict_types=1);require dirname(__DIR__).'/_bootstrap.php';require_get();$user=api_user();$scan=(int)input('scan_id');$s=db()->prepare("SELECT q.id,q.question_text,q.question_type,q.sort_order FROM hunt_questions q JOIN hunt_scans s ON s.id=? AND s.user_id=? AND s.result='VALIDATED' WHERE q.hunt_id=s.hunt_id AND (q.location_id=s.location_id OR q.location_id IS NULL) AND q.status='ACTIVE' ORDER BY q.sort_order,q.id");$s->execute([$scan,$user['id']]);$items=$s->fetchAll();$o=db()->prepare('SELECT id,option_text FROM hunt_question_options WHERE question_id=? ORDER BY sort_order,id');foreach($items as &$item){$o->execute([$item['id']]);$item['options']=$o->fetchAll();}unset($item);json_response(true,'Questions',['items'=>$items]);
